def reload_pool(rec):
    view = env.ref('hr_pool.view_hr_pool_form', raise_if_not_found=False)
    action = {
        'type': 'ir.actions.act_window',
        'name': rec.x_name or rec.display_name or 'HR Pool',
        'res_model': rec._name,
        'res_id': rec.id,
        'view_mode': 'form',
        'target': 'current',
    }
    if view:
        action['views'] = [(view.id, 'form')]
    return action


for rec in records.sudo():
    if rec.x_f0001_state in ('signature_requested', 'signed'):
        action = toast(
            'F-0001',
            'لا يمكن إعادة إنشاء نموذج F-0001 بعد دخوله مسار التوقيع.',
            'warning',
            True,
            reload_pool(rec),
        )
        continue

    if not rec.x_name:
        action = toast('F-0001', 'يجب حفظ اسم المرشح قبل إنشاء نموذج F-0001.', 'warning', True, reload_pool(rec))
        continue

    if not rec.x_phone:
        action = toast('F-0001', 'يجب إدخال رقم هاتف المرشح قبل إنشاء نموذج F-0001.', 'warning', True, reload_pool(rec))
        continue

    if not rec.x_email:
        action = toast('F-0001', 'يجب إدخال البريد الإلكتروني للمرشح قبل إنشاء نموذج F-0001.', 'warning', True, reload_pool(rec))
        continue

    if not rec.x_qualification_type:
        action = toast('F-0001', 'يجب اختيار نوع المؤهل العلمي قبل إنشاء نموذج F-0001.', 'warning', True, reload_pool(rec))
        continue

    if not rec.x_specialisation:
        action = toast('F-0001', 'يجب إدخال التخصص / مجال الدراسة قبل إنشاء نموذج F-0001.', 'warning', True, reload_pool(rec))
        continue

    generated_on = datetime.datetime.now()
    form_code = 'MCEP-HR-F-0001'

    document_reference = rec.x_f0001_document_reference
    if not document_reference:
        document_reference = '%s-%05d' % (form_code, rec.id)

    rec.write({
        'x_f0001_document_reference': document_reference,
        'x_f0001_responsible_user_id': env.user.id,
    })
    rec = rec.sudo().browse(rec.id)

    report_xmlid = 'hr_pool.action_report_hr_pool_f0001_job_application'
    pdf_content, _content_type = env['ir.actions.report'].sudo()._render_qweb_pdf(report_xmlid, [rec.id])

    filename = '%s - طلب التوظيف F-0001.pdf' % (document_reference,)

    attachment = env['ir.attachment'].sudo().create({
        'name': filename,
        'type': 'binary',
        'raw': pdf_content,
        'mimetype': 'application/pdf',
        'res_model': rec._name,
        'res_id': rec.id,
    })

    rec.write({
        'x_f0001_pdf_attachment_id': attachment.id,
        'x_f0001_generated_on': generated_on,
        'x_f0001_state': 'generated',
    })

    rec.message_post(
        body='تم إنشاء نموذج طلب التوظيف F-0001 وربطه بسجل المرشح.',
        subtype_xmlid='mail.mt_note',
        attachment_ids=[attachment.id],
    )

    action = toast('F-0001', 'تم إنشاء نموذج F-0001 بنجاح.', 'success', False, reload_pool(rec))
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

