def get_or_create_role(name, fallbacks):
    role = sign_role_model.search([('name', '=', name)], order='id asc', limit=1)
    if role:
        return role
    for fallback in fallbacks:
        role = sign_role_model.search([('name', '=', fallback)], order='id asc', limit=1)
        if role:
            return role
    return sign_role_model.create({'name': name})


def candidate_partner(rec):
    email = (rec.x_email or '').strip()
    if not email:
        return False

    partner = partner_model.search([('email', '=', email)], order='id asc', limit=1)
    if partner:
        vals = {}
        if rec.x_name and not partner.name:
            vals['name'] = rec.x_name
        if rec.x_phone and not partner.phone:
            vals['phone'] = rec.x_phone
        if vals:
            partner.write(vals)
        return partner

    return partner_model.create({
        'name': rec.x_name or email,
        'email': email,
        'phone': rec.x_phone or False,
    })


def signer_order_vals(order):
    vals = {'mail_sent_order': order}
    for optional_field in ('sequence', 'sign_order'):
        if optional_field in sign_send_signer_model._fields:
            vals[optional_field] = order
    return vals


if not signature_type:
    action = toast('Odoo Sign setup missing', 'Signature field type sign.sign_item_type_signature was not found.', 'warning', True)
else:
    candidate_role = get_or_create_role('Candidate', ['Applicant', 'Customer', 'Signatory'])

    for rec in records.sudo():
        if rec.x_f0001_state == 'signed' or rec.x_f0001_signed_attachment_id:
            action = toast('Already signed', 'F-0001 is already signed for this candidate.', 'warning', False, reload_pool(rec))
            continue

        if rec.x_f0001_sign_request_res_id:
            existing_request = sign_request_model.browse(rec.x_f0001_sign_request_res_id)
            if existing_request.exists() and (existing_request.state or '') not in ('cancelled', 'canceled'):
                action = toast('Duplicate Sign request blocked', 'An active Odoo Sign request already exists for F-0001. Use Sync instead.', 'warning', True, reload_pool(rec))
                continue

        if rec.x_f0001_state != 'generated' or not rec.x_f0001_pdf_attachment_id:
            action = toast('Generate PDF first', 'Generate the F-0001 PDF before sending it to Odoo Sign.', 'warning', False, reload_pool(rec))
            continue

        candidate_sign_partner = candidate_partner(rec)
        if not candidate_sign_partner or not candidate_sign_partner.email:
            action = toast('Missing candidate email', 'The candidate needs an email before sending F-0001 to Sign.', 'warning', True, reload_pool(rec))
            continue

        pdf_attachment = rec.x_f0001_pdf_attachment_id.sudo()
        filename = pdf_attachment.name or ('%s - F-0001 Job Application.pdf' % (rec.x_f0001_document_reference or 'MCEP-HR-F-0001'))
        sent_on = datetime.datetime.now()
        validity_date = datetime.date.today() + datetime.timedelta(days=60)

        sign_template = sign_template_model.create({
            'name': filename,
            'user_id': env.user.id,
            'signature_request_validity': 60,
        })

        sign_document = sign_document_model.create({
            'template_id': sign_template.id,
            'attachment_id': pdf_attachment.id,
            'name': filename,
            'sequence': 1,
        })

        # F-0001 accepted one-page geometry after Slice 1F-D rendering.
        # Candidate signature item is placed inside the lower blank signature box.
        # Coordinates are normalized fractions of the PDF page.
        sign_item_model.create({
            'document_id': sign_document.id,
            'type_id': signature_type.id,
            'responsible_id': candidate_role.id,
            'page': 1,
            'posX': 0.225,
            'posY': 0.895,
            'width': 0.315,
            'height': 0.045,
            'required': True,
            'name': 'Candidate Signature',
            'alignment': 'left',
            'constant': False,
        })

        subject = 'Signature Request - %s' % filename
        body = '<p>Please review and sign the attached F-0001 Job Application form.</p>'

        send_vals = {
            'template_id': sign_template.id,
            'signer_id': candidate_sign_partner.id,
            'subject': subject,
            'body': body,
            'validity': validity_date,
            'certificate_reference': False,
            'reminder_enabled': False,
            'model': 'x_hr.pool',
            'res_ids': str([rec.id]),
        }
        if 'set_sign_order' in sign_send_model._fields:
            send_vals['set_sign_order'] = True

        send_request = sign_send_model.create(send_vals)

        signer_line = send_request.signer_ids.filtered(lambda line: line.role_id.id == candidate_role.id)[:1]
        ordered_vals = signer_order_vals(1)
        ordered_vals['partner_id'] = candidate_sign_partner.id

        if signer_line:
            signer_line.sudo().write(ordered_vals)
        else:
            create_vals = signer_order_vals(1)
            create_vals.update({
                'sign_send_request_id': send_request.id,
                'role_id': candidate_role.id,
                'partner_id': candidate_sign_partner.id,
            })
            sign_send_signer_model.create(create_vals)

        if 'set_sign_order' in send_request._fields:
            send_request.sudo().write({'set_sign_order': True})

        send_request.send_request()

        generated_request = sign_request_model.search([
            ('template_id', '=', sign_template.id),
        ], order='create_date desc, id desc', limit=1)

        if generated_request:
            rec.write({
                'x_f0001_state': 'signature_requested',
                'x_f0001_sent_on': sent_on,
                'x_f0001_sign_request_res_id': generated_request.id,
                'x_f0001_sign_request_state': generated_request.state or 'sent',
                'x_f0001_sign_request_reference': generated_request.reference or filename,
                'x_f0001_sign_request_url': '/odoo/sign/%s' % generated_request.id,
                'x_f0001_responsible_user_id': env.user.id,
                'x_f0001_notes': ((rec.x_f0001_notes or '') + '\nNative Odoo Sign request created for F-0001 on %s. Request ID: %s. Candidate: %s.' % (sent_on, generated_request.id, candidate_sign_partner.display_name)).strip(),
            })

            rec.message_post(
                body='تم إرسال نموذج طلب التوظيف F-0001 للتوقيع عبر توقيع أودو. رقم طلب التوقيع: %s.' % generated_request.id,
                subtype_xmlid='mail.mt_note',
                attachment_ids=[pdf_attachment.id],
            )

            action = toast('Sent to Sign', 'F-0001 was sent to the candidate signer.', 'success', False, reload_pool(rec))
        else:
            rec.write({
                'x_f0001_sent_on': sent_on,
                'x_f0001_sign_request_state': 'lookup_failed_after_send_request',
                'x_f0001_sign_request_reference': filename,
                'x_f0001_notes': ((rec.x_f0001_notes or '') + '\nNative Odoo Sign send_request() executed for F-0001 on %s, but the generated sign.request could not be located automatically. Dynamic template ID: %s.' % (sent_on, sign_template.id)).strip(),
            })
            action = toast('Sign request lookup failed', 'Send request executed, but the generated sign.request was not found automatically. Check the Sign app.', 'warning', True, reload_pool(rec))

        break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

