def looks_like_certificate(attachment):
    name = (attachment.name or '').lower()
    return (
        'certificate' in name
        or 'completion' in name
        or 'completed' in name
        or 'history' in name
        or 'audit' in name
        or 'trail' in name
        or 'شهادة' in name
        or 'إكمال' in name
        or 'اكمال' in name
    )


for rec in records.sudo():
    # Sync generated PDF state first if needed.
    if not rec.x_f0001_pdf_attachment_id:
        generated_pdf = attachment_model.search([
            ('res_model', '=', rec._name),
            ('res_id', '=', rec.id),
            ('mimetype', '=', 'application/pdf'),
            ('name', 'ilike', 'F-0001'),
        ], order='create_date desc, id desc', limit=1)
        if generated_pdf:
            rec.write({
                'x_f0001_pdf_attachment_id': generated_pdf.id,
                'x_f0001_generated_on': rec.x_f0001_generated_on or generated_pdf.create_date or datetime.datetime.now(),
                'x_f0001_state': 'generated',
            })

    elif rec.x_f0001_state == 'draft':
        rec.write({
            'x_f0001_generated_on': rec.x_f0001_generated_on or rec.x_f0001_pdf_attachment_id.create_date or datetime.datetime.now(),
            'x_f0001_state': 'generated',
        })

    if not rec.x_f0001_sign_request_res_id:
        action = toast('PDF state synced', 'No linked Odoo Sign request was found yet. PDF generation state has been refreshed where possible.', 'success', False, reload_pool(rec))
        continue

    sign_request = sign_request_model.browse(rec.x_f0001_sign_request_res_id)
    if not sign_request.exists():
        rec.write({'x_f0001_sign_request_state': 'missing_sign_request'})
        action = toast('Missing Sign request', 'The linked Odoo Sign request no longer exists or cannot be accessed.', 'warning', True, reload_pool(rec))
        continue

    request_state = sign_request.state or 'unknown'

    values = {
        'x_f0001_sign_request_state': request_state,
        'x_f0001_sign_request_reference': sign_request.reference or rec.x_f0001_sign_request_reference,
    }

    if request_state not in ('signed', 'completed'):
        if rec.x_f0001_state != 'signature_requested':
            values['x_f0001_state'] = 'signature_requested'
        if not rec.x_f0001_sent_on:
            values['x_f0001_sent_on'] = sign_request.create_date or datetime.datetime.now()
        rec.write(values)
        rec.message_post(
            body='تمت مزامنة حالة توقيع نموذج F-0001. الحالة الحالية: %s.' % request_state,
            subtype_xmlid='mail.mt_note',
        )
        action = toast('Sign state synced', 'F-0001 Sign request is currently: %s.' % request_state, 'warning', False, reload_pool(rec))
        continue

    completed_attachments = sign_request.completed_document_attachment_ids

    related_attachments = attachment_model.search([
        ('res_model', '=', 'sign.request'),
        ('res_id', '=', sign_request.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    pool_attachments = attachment_model.search([
        ('res_model', '=', rec._name),
        ('res_id', '=', rec.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    all_attachments = completed_attachments | related_attachments | pool_attachments

    signed_native = False
    certificate_native = False

    for attachment in all_attachments:
        if rec.x_f0001_pdf_attachment_id and attachment.id == rec.x_f0001_pdf_attachment_id.id:
            continue
        if looks_like_certificate(attachment):
            if not certificate_native:
                certificate_native = attachment
        elif not signed_native:
            signed_native = attachment

    if not signed_native:
        rec.write({
            'x_f0001_sign_request_state': 'signed_no_business_document_found',
            'x_f0001_notes': ((rec.x_f0001_notes or '') + '\nOdoo Sign request %s is signed, but no signed business PDF was found during F-0001 sync on %s.' % (sign_request.id, datetime.datetime.now())).strip(),
        })
        action = toast('Signed PDF not found', 'The Sign request is signed, but the completed signed PDF was not found yet. Try Sync again after Odoo finishes processing.', 'warning', True, reload_pool(rec))
        continue

    signed_copy = rec.x_f0001_signed_attachment_id
    if signed_copy and looks_like_certificate(signed_copy):
        signed_copy = False
    if signed_copy and rec.x_f0001_pdf_attachment_id and signed_copy.id == rec.x_f0001_pdf_attachment_id.id:
        signed_copy = False

    if not signed_copy:
        signed_name = signed_native.name or ('Signed F-0001 - %s.pdf' % (rec.x_name or rec.x_f0001_document_reference or rec.id))
        if signed_native.res_model == rec._name and signed_native.res_id == rec.id:
            signed_copy = signed_native
        else:
            signed_copy = signed_native.copy({
                'name': signed_name,
                'res_model': rec._name,
                'res_id': rec.id,
            })

    certificate_copy = rec.x_f0001_sign_certificate_attachment_id
    if not certificate_copy and certificate_native:
        certificate_name = certificate_native.name or ('Sign Certificate F-0001 - %s.pdf' % (rec.x_name or rec.x_f0001_document_reference or rec.id))
        if certificate_native.res_model == rec._name and certificate_native.res_id == rec.id:
            certificate_copy = certificate_native
        else:
            certificate_copy = certificate_native.copy({
                'name': certificate_name,
                'res_model': rec._name,
                'res_id': rec.id,
            })

    signed_on = False
    if sign_request.write_date:
        signed_on = sign_request.write_date

    signer_items = sign_request.request_item_ids.filtered(lambda item: item.state == 'completed')
    for signer_item in signer_items:
        if signer_item.write_date and (not signed_on or signer_item.write_date > signed_on):
            signed_on = signer_item.write_date

    if not signed_on and sign_request.completion_date:
        signed_on = datetime.datetime.combine(sign_request.completion_date, datetime.time(12, 0, 0))

    if not signed_on:
        signed_on = datetime.datetime.now()

    write_vals = {
        'x_f0001_state': 'signed',
        'x_f0001_signed_on': signed_on,
        'x_f0001_signed_attachment_id': signed_copy.id,
        'x_f0001_sign_request_state': request_state,
        'x_f0001_sign_request_reference': sign_request.reference or rec.x_f0001_sign_request_reference,
        'x_f0001_sign_request_url': rec.x_f0001_sign_request_url or ('/odoo/sign/%s' % sign_request.id),
        'x_f0001_notes': ((rec.x_f0001_notes or '') + '\nNative Odoo Sign completion synced for F-0001 on %s. Sign request ID: %s. Signed artifact: %s.' % (datetime.datetime.now(), sign_request.id, signed_copy.name)).strip(),
    }

    if not rec.x_f0001_sent_on:
        write_vals['x_f0001_sent_on'] = sign_request.create_date or signed_on

    if certificate_copy:
        write_vals['x_f0001_sign_certificate_attachment_id'] = certificate_copy.id

    rec.write(write_vals)

    attachment_ids = [signed_copy.id]
    if certificate_copy:
        attachment_ids.append(certificate_copy.id)

    rec.message_post(
        body='تم توقيع نموذج طلب التوظيف F-0001 عبر توقيع أودو وربط النسخة الموقعة والشهادة، عند توفرها، بسجل المرشح.',
        subtype_xmlid='mail.mt_note',
        attachment_ids=attachment_ids,
    )

    action = toast('F-0001 signed', 'F-0001 Sign result was synced and the signed PDF was linked to the candidate pool record.', 'success', False, reload_pool(rec))
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
